import{_ as a,o,c as s,a2 as r}from"./chunks/framework.CDpkVv68.js";const h=JSON.parse('{"title":"Libros de hechizos, pergaminos y reactivos","description":"","frontmatter":{},"headers":[],"relativePath":"es/guide/magic/spellbooks-scrolls-and-reagents.md","filePath":"es/guide/magic/spellbooks-scrolls-and-reagents.md"}'),i={name:"es/guide/magic/spellbooks-scrolls-and-reagents.md"};function n(t,e,l,c,d,p){return o(),s("div",null,[...e[0]||(e[0]=[r('<h1 id="spellbooks-scrolls-reagents" tabindex="-1">Libros de hechizos, pergaminos y reactivos <a class="header-anchor" href="#spellbooks-scrolls-reagents" aria-label="Enlace permanente a &quot;Libros de hechizos, pergaminos y reactivos&quot;">​</a></h1><p><strong>Estado:</strong> Propuesto · Disponibilidad no confirmada.</p><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Enlace permanente a &quot;TL;DR&quot;">​</a></h2><ul><li>El conocimiento mágico aprendido debería sobrevivir a la muerte.</li><li>Los libros raros, pergaminos de lanzamiento y reactivos siguen siendo recursos físicos con riesgo de saqueo.</li><li>Los pergaminos ofrecen acceso táctico temporal, no aprendizaje permanente automático.</li></ul><p><span id="spellbooks-scrolls-and-reagents"></span><span id="at-a-glance"></span></p><h2 id="how-it-works" tabindex="-1">Cómo funciona <a class="header-anchor" href="#how-it-works" aria-label="Enlace permanente a &quot;Cómo funciona&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Elemento</th><th>Qué significa para el jugador</th></tr></thead><tbody><tr><td>Libro personal</td><td>Representa la magia conocida y normalmente no debería caer al morir; su protección y sustitución exactas siguen abiertas.</td></tr><tr><td>Grimorio raro</td><td>Puede contener anotaciones, patrones o ventajas de consulta valiosos y ser saqueable.</td></tr><tr><td>Pergamino de lanzamiento</td><td>Un consumible puede dar acceso temporal a un hechizo, una variante o una consulta más rápida; los requisitos y el consumo al fallar siguen abiertos.</td></tr><tr><td>Reactivos</td><td>Los materiales físicos pueden actuar como catalizadores o estabilizadores. Las recetas y sustituciones siguen abiertas.</td></tr></tbody></table><h2 id="compared-with-classic-uo" tabindex="-1">Comparado con UO clásico <a class="header-anchor" href="#compared-with-classic-uo" aria-label="Enlace permanente a &quot;Comparado con UO clásico&quot;">​</a></h2><table tabindex="0"><thead><tr><th>UO clásico</th><th>Orientación de Syrolands</th></tr></thead><tbody><tr><td>Los pergaminos de Magery pueden lanzarse o añadirse a un libro de hechizos.</td><td>Los pergaminos de lanzamiento normales dan acceso temporal sin enseñar permanentemente el patrón.</td></tr><tr><td>Los libros reúnen hechizos; lanzarlos utiliza recursos mágicos.</td><td>Se separa el conocimiento persistente de referencias físicas valiosas y consumibles en riesgo.</td></tr></tbody></table><p>Las reglas de UO varían según la época y el shard. <a href="https://uo.com/wiki/ultima-online-wiki/skills/an-introduction-to-spellcasting/" target="_blank" rel="noreferrer">UO oficial: lanzamiento de hechizos</a>.</p><h2 id="example" tabindex="-1">Ejemplo <a class="header-anchor" href="#example" aria-label="Enlace permanente a &quot;Ejemplo&quot;">​</a></h2><p>Un pergamino de Dispel de emergencia podría reducir el tiempo de consulta de un hechizo sin preparar a cambio de un consumible. No enseñaría Dispel permanentemente ni garantizaría el éxito del lanzamiento.</p><h2 id="progression-trade-offs" tabindex="-1">Progresión y contrapartidas <a class="header-anchor" href="#progression-trade-offs" aria-label="Enlace permanente a &quot;Progresión y contrapartidas&quot;">​</a></h2><p>Proteger el conocimiento no es un seguro general del equipo. Los pergaminos y reactivos generalmente caen al morir; los objetos especiales de enseñanza y la frontera entre libros personales y grimorios raros aún necesitan reglas.</p><h2 id="related" tabindex="-1">Relacionado <a class="header-anchor" href="#related" aria-label="Enlace permanente a &quot;Relacionado&quot;">​</a></h2><p><a href="/Syrolands-Public/es/guide/professions/inscription.html">Inscription</a> · <a href="/Syrolands-Public/es/guide/magic/memory-and-familiarity.html">Memoria</a> · <a href="/Syrolands-Public/es/guide/professions/alchemy.html">Alchemy</a></p><h2 id="full-design-specification" tabindex="-1">Especificación de diseño completa <a class="header-anchor" href="#full-design-specification" aria-label="Enlace permanente a &quot;Especificación de diseño completa&quot;">​</a></h2><p>Consulta la especificación de diseño: <a href="/Syrolands-Public/es/game-design/magic/spellbooks-scrolls-and-reagents.html">Libros de hechizos, pergaminos y reactivos</a>.</p>',18)])])}const u=a(i,[["render",n]]);export{h as __pageData,u as default};
